use crate::presentation::io::sqlite::snapshot::*;
use semio_framework_os_kernel::{ArtifactSqliteSnapshot,sqlite_snapshot::*};
fn fixture()->SemioPresentationSnapshot{let f:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let frame=SlideFrame{origin:SemioPoint2{x:-1.0,y:2.0},width:3.5,height:4.25};let kinds=vec![PlaceholderKind::Title,PlaceholderKind::Subtitle,PlaceholderKind::Body,PlaceholderKind::Footer,PlaceholderKind::SlideNumber,PlaceholderKind::DateTime,PlaceholderKind::Other{value:"".into()}];let mut shapes:Vec<SlideShape>=kinds.into_iter().map(|kind|SlideShape::Placeholder{frame,kind}).collect();shapes.push(SlideShape::TextBox{frame,blocks:vec![DocBlock::Paragraph{style_id:Some("external-style".into()),runs:vec![crate::standards::v1::subsets::document::schema::snapshot::DocRun::plain(f["text"].as_str().unwrap())]},DocBlock::Image{image_id:"external-image".into(),alt:"".into(),width:None,height:Some(0.0)}]});shapes.push(SlideShape::Picture{frame,image:SlidePictureImage{asset_id:"".into(),mime:"image/png".into(),bytes:vec![0,255,127]}});shapes.push(SlideShape::Table{frame,rows:vec![SlideTableRow{cells:vec![SlideTableCell{blocks:vec![DocBlock::Quote{blocks:vec![DocBlock::PageBreak]}]},SlideTableCell{blocks:vec![]}]}]});SemioPresentationSnapshot{schema:f["schema"].as_str().unwrap().into(),masters:vec![SlideMaster{id:"master".into(),shapes:vec![SlideShape::Placeholder{frame,kind:PlaceholderKind::Title}]}],layouts:vec![SlideLayout{id:"layout".into(),master_id:"master".into(),shapes:vec![]}],slides:vec![Slide{id:f["slideId"].as_str().unwrap().into(),layout_id:Some("layout".into()),shapes,notes:vec![DocBlock::Code{language:Some("".into()),text:"notes".into()}]},Slide{id:"".into(),layout_id:None,shapes:vec![],notes:vec![]}]}}
fn project(s:&SemioPresentationSnapshot)->SqliteDatabase{s.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap()}
fn restore(db:&SqliteDatabase)->Result<SemioPresentationSnapshot, semio_framework_value::ValueError>{SemioPresentationSnapshot::from_sqlite_database(db,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default()))}
#[test]
